(() => {
'use strict';const $=s=>document.querySelector(s),core=window.EquationCandidates;
function math(host,tex){const span=document.createElement('span');span.dataset.tex=tex;host.replaceChildren(span);}
function rational(){const a=Number($('#excluded-value').value),b=Number($('#target-value').value),r=core.rational(a,b);$('#target-output').value=b;math($('#rational-equation'),`\\frac{x^2-${a*a}}{x-${a}}=${b},\\quad x\\ne${a}`);math($('#rational-candidate'),`x+${a}=${b}\\quad\\Longrightarrow\\quad x=${r.candidate}`);$('#rational-feedback').textContent=r.valid?`Kandidat ${r.candidate} diperbolehkan. Substitusi pada pecahan semula memberi ${b}, sama dengan ruas kanan. Jadi kandidat ini adalah solusi.`:`Kandidat ${r.candidate} dilarang karena membuat penyebut nol. Tidak ada solusi: faktor yang disederhanakan tidak menghapus syarat awal.`;}
$('#excluded-value').addEventListener('change',rational);$('#target-value').addEventListener('input',rational);rational();
function root(){const c=core.roots.find(item=>item.id===$('#root-case').value),x=c.candidates[Number($('#candidate-index').value)],rad=c.c?`x+${c.c}`:'x',right=c.d?`x-${c.d}`:'x';math($('#original-root'),`\\sqrt{${rad}}=${right}`);math($('#squared-root'),`${rad}=(${right})^2\\quad\\Longrightarrow\\quad x\\in\\{${c.candidates.join(',')}\\}`);const result=core.checkRoot(c.c,c.d,x);math($('#checked-root'),`x=${x}:\\quad\\sqrt{${x+c.c}}${result.status==='valid'?'=':'\\ne'}${x-c.d}`);$('#root-feedback').textContent=result.status==='valid'?`Kandidat ${x} memenuhi persamaan asal. Radikan tidak negatif, ruas kanan tidak negatif, dan kedua ruas sama. Ini solusi yang sah.`:`Kandidat ${x} memenuhi persamaan setelah kuadrat, tetapi ruas kanan persamaan asal negatif. Akar utama tidak negatif, sehingga kedua ruas tidak sama. Kandidat ini ekstran dan ditolak.`;}
$('#root-case').addEventListener('change',()=>{$('#candidate-index').value='0';root();});$('#candidate-index').addEventListener('change',root);root();
const questions=[
[String.raw`\frac3{x-1}=2`,[String.raw`\{1\}`,String.raw`\{\frac52\}`,String.raw`\varnothing`],1,'Penyebut melarang satu. Mengalikan dengan penyebut dan menyelesaikan persamaan memberi lima per dua, yang memenuhi persamaan awal.'],
[String.raw`\frac{x^2-4}{x-2}=4`,[String.raw`\{2\}`,String.raw`\{0\}`,String.raw`\varnothing`],2,'Setelah penyederhanaan kandidatnya dua, tetapi dua dilarang pada pecahan awal. Jadi tidak ada solusi.'],
[String.raw`\frac{x^2-4}{x-2}=5`,[String.raw`\{3\}`,String.raw`\{2,3\}`,String.raw`\varnothing`],0,'Pada domain selain dua, ruas kiri sama dengan masukan ditambah dua. Kandidat tiga diperbolehkan dan memenuhi.'],
[String.raw`\sqrt{x+2}=x`,[String.raw`\{-1,2\}`,String.raw`\{2\}`,String.raw`\{-1\}`],1,'Kedua kandidat memenuhi persamaan hasil kuadrat. Negatif satu gagal pada persamaan asal karena akar utamanya positif satu.'],
[String.raw`\sqrt x=x-2`,[String.raw`\{1,4\}`,String.raw`\{1\}`,String.raw`\{4\}`],2,'Ruas kanan harus tidak negatif, jadi masukan sekurang-kurangnya dua. Kandidat satu ditolak, sedangkan empat menghasilkan dua sama dengan dua.'],
[String.raw`\sqrt{x-2}=-1`,[String.raw`\{3\}`,String.raw`\varnothing`,String.raw`\{-1\}`],1,'Akar utama tidak negatif sehingga tidak mungkin sama dengan negatif satu. Kandidat tiga dari pengkuadratan tidak sah.'],
[String.raw`\frac1x+\frac1{x-1}=\frac3{x(x-1)}`, [String.raw`\{2\}`,String.raw`\{0,1,2\}`,String.raw`\{1\}`],0,'Larangan awal adalah nol dan satu. Mengalikan setiap suku dengan hasil kali penyebut memberi dua kali masukan dikurangi satu sama dengan tiga. Kandidat dua memenuhi.'],
[String.raw`u^2=v^2\quad\text{selalu berarti }u=v?`,[String.raw`\text{Ya}`,String.raw`\text{Tidak}`],1,'Kuadrat satu dan negatif satu sama, tetapi bilangannya berbeda. Karena itu kandidat setelah kuadrat perlu diperiksa pada persamaan asal.']
];const solved=new Set();
questions.forEach(([tex,options,answer,reason],i)=>{const box=document.createElement('fieldset'),legend=document.createElement('legend'),number=document.createElement('span'),formula=document.createElement('span');number.dataset.noEquation='';number.textContent=`Latihan ${i+1}: `;formula.dataset.tex=tex;legend.append(number,formula);box.append(legend);options.forEach((option,j)=>{const label=document.createElement('label'),radio=document.createElement('input'),copy=document.createElement('span');radio.type='radio';radio.name=`candidate-q${i}`;radio.value=String(j);copy.dataset.tex=option;label.append(radio,copy);box.append(label);});const button=document.createElement('button');button.type='button';button.textContent='Periksa jawaban';const feedback=document.createElement('p');feedback.setAttribute('role','status');button.addEventListener('click',()=>{const selected=box.querySelector('input:checked');if(!selected){feedback.textContent='Pilih satu jawaban terlebih dahulu.';return;}const ok=Number(selected.value)===answer;if(ok)solved.add(i);feedback.textContent=(ok?'Tepat. ':'Belum tepat. ')+reason;feedback.className=ok?'correct':'incorrect';$('#candidate-progress').textContent=`${solved.size} dari 8 latihan pernah dijawab tepat.`;});box.addEventListener('change',()=>{feedback.textContent='Jawaban berubah. Periksa kembali untuk melihat tanggapan.';feedback.className='';});box.append(button,feedback);$('#candidate-questions').append(box);});$('#candidate-progress').textContent='0 dari 8 latihan pernah dijawab tepat.';
try{$('#candidate-reflection').value=localStorage.getItem('fondasi-candidate-reflection')||'';}catch{$('#candidate-save').textContent='Catatan belum dapat dimuat. Salin bila diperlukan.';}
$('#candidate-reflection').addEventListener('input',()=>{try{localStorage.setItem('fondasi-candidate-reflection',$('#candidate-reflection').value);$('#candidate-save').textContent='Catatan tersimpan di peramban ini.';}catch{$('#candidate-save').textContent='Catatan belum dapat disimpan. Salin bila diperlukan.';}});
})();
